@extends('admin.layouts.app') @section('title','Role permissions') @section('content')<h1 class="page-title mb-4">{{ $role->exists?'Edit role':'Create role' }}</h1><form method="POST" action="{{ $role->exists?route('admin.roles.update',$role):route('admin.roles.store') }}">@csrf @if($role->exists)@method('PUT')@endif<div class="content-card mb-4"><div class="row g-3"><div class="col-md-6"><label class="form-label">Role name</label><input class="form-control" name="name" value="{{ old('name',$role->name) }}" required></div><div class="col-md-6"><label class="form-label">Description</label><input class="form-control" name="description" value="{{ old('description',$role->description) }}"></div></div></div><div class="content-card"><h2 class="section-title">Permissions</h2>@foreach($permissions as $group=>$items)<h3 class="fs-6 text-capitalize mt-3">{{ $group?:'General' }}</h3><div class="row g-2">@foreach($items as $permission)<div class="col-md-4"><label class="form-check"><input class="form-check-input" type="checkbox" name="permissions[]" value="{{ $permission->id }}" @checked(in_array($permission->id,old('permissions',$role->permissions->pluck('id')->all())))><span class="form-check-label">{{ $permission->name }}</span></label></div>@endforeach</div>@endforeach<button class="btn btn-primary mt-4">Save role</button></div></form>@endsection